steps.starter:
{{pins}}
#include <WiFi.h>
#include <WebServer.h>

WebServer server(80);  // web pages use port 80

void homePage() {
  server.send(200, "text/html", "<h1>Hello from my board!</h1>");
}

void setup() {
  Serial.begin(115200);
  WiFi.softAP("ArduinoPath-Sam", "circuit123");
  server.on("/", homePage);  // "/" is the home page
  server.begin();
  Serial.print("Open http://");
  Serial.println(WiFi.softAPIP());
}

void loop() {
  server.handleClient();  // answer anyone asking for a page
}

